macro_rules! deps {
    () => {
        SpanMode!();
    };
}

macro_rules! indent_block_with_lines {
    () => {
        deps!();
        fn indent_block_with_lines (lines : & [& str] , buf : & mut String , indent : usize , indent_amount : usize , prefix : & str , style : SpanMode ,) { let indent_spaces = indent * indent_amount ; if lines . is_empty () { return ; } else if indent_spaces == 0 { for line in lines { buf . push_str (prefix) ; if indent == 0 { match style { SpanMode :: Open { .. } => buf . push_str (LINE_OPEN) , SpanMode :: Retrace { .. } => buf . push_str (LINE_OPEN) , SpanMode :: Close { .. } => buf . push_str (LINE_CLOSE) , SpanMode :: PreOpen | SpanMode :: PostClose => { } SpanMode :: Event => { } } } buf . push_str (line) ; buf . push ('\n') ; } return ; } let mut s = String :: with_capacity (indent_spaces + prefix . len ()) ; s . push_str (prefix) ; for _ in 0 .. (indent_spaces - indent_amount) { s . push (' ') ; } buf . push_str (& s) ; match style { SpanMode :: PreOpen => { buf . push (LINE_OPEN2) ; for _ in 1 .. (indent_amount / 2) { buf . push_str (LINE_HORIZ) ; } buf . push_str (LINE_OPEN) ; } SpanMode :: Open { verbose : false } | SpanMode :: Retrace { verbose : false } => { buf . push (LINE_OPEN2) ; for _ in 1 .. indent_amount { buf . push_str (LINE_HORIZ) ; } buf . push_str (LINE_OPEN) ; } SpanMode :: Open { verbose : true } | SpanMode :: Retrace { verbose : true } => { buf . push (' ') ; for _ in 1 .. (indent_amount / 2) { buf . push (' ') ; } if indent_amount > 1 { buf . push (LINE_OPEN2) ; } for _ in (indent_amount / 2) .. (indent_amount - 1) { buf . push_str (LINE_HORIZ) ; } if indent_amount > 1 { buf . push_str (LINE_OPEN) ; } else { buf . push (' ') ; } } SpanMode :: Close { verbose : false } => { buf . push (LINE_CLOSE2) ; for _ in 1 .. indent_amount { buf . push_str (LINE_HORIZ) ; } buf . push_str (LINE_CLOSE) ; } SpanMode :: Close { verbose : true } => { buf . push (' ') ; for _ in 1 .. (indent_amount / 2) { buf . push (' ') ; } if indent_amount > 1 { buf . push (LINE_CLOSE2) ; } for _ in (indent_amount / 2) .. (indent_amount - 1) { buf . push_str (LINE_HORIZ) ; } if indent_amount > 1 { buf . push_str (LINE_CLOSE) ; } else { buf . push (' ') ; } } SpanMode :: PostClose => { buf . push (LINE_CLOSE2) ; for _ in 1 .. (indent_amount / 2) { buf . push_str (LINE_HORIZ) ; } buf . push_str (LINE_CLOSE) ; } SpanMode :: Event => { buf . push_str (LINE_BRANCH) ; for _ in 0 .. (indent_amount - 1) { buf . push_str (LINE_HORIZ) ; } } } buf . push_str (lines [0]) ; buf . push ('\n') ; match style { SpanMode :: Open { .. } | SpanMode :: Retrace { .. } => s . push_str ("  ") , SpanMode :: Close { .. } => s . push (' ') , _ => { } } s . push_str (LINE_VERT) ; for _ in 1 ..= indent_amount { s . push (' ') ; } for line in & lines [1 ..] { buf . push_str (& s) ; buf . push_str (line) ; buf . push ('\n') ; } }
    };
}

indent_block_with_lines!()